import { Command, Option } from "commander";

import { environmentNames } from "../../api/env.ts";
import { administrationNamespace } from "../../config/cli-help-policy.ts";
import type { OpenApiCommandSpec } from "../../mcp-server/contract.ts";

/**
 * Parse the root environment with Commander before deciding whether saved auth is needed. This
 * keeps the API host and host-partitioned personal credential on the same environment while local
 * CLI commands and public API commands remain usable without credential access.
 *
 * Administration-section visibility depends on a materialized ADMIN_API_KEY or AUTH_TOKEN, so
 * surfaces that enumerate or resolve the command tree — root help, completion, command-catalog,
 * docs, the help builtin — and every administration-namespace invocation materialize saved auth
 * before the visibility filter runs. Argv that resolves to no generated spec also materializes:
 * unknown-command recovery enumerates the visibility-filtered tree for cross-namespace hints, so
 * a saved credential must be loaded for administration targets to surface. A machine with no saved
 * auth config pays nothing: materialization is a no-op there. Builtin `--help` renders stay
 * credential-free.
 */
export function commandNeedsMaterializedAuth(
  argv: readonly string[],
  specs: readonly OpenApiCommandSpec[],
): boolean {
  // Only flags before the option terminator select help/version renders.
  const terminator = argv.indexOf("--");
  const optionScan = argv.slice(0, terminator === -1 ? argv.length : terminator);
  if (optionScan.some((entry) => entry === "--version" || entry === "-V")) return false;
  const preflight = new Command()
    .exitOverride()
    .configureOutput({ writeErr: () => undefined })
    .addOption(
      new Option(
        "--environment <environment>",
        "route all API calls to a mapped API environment",
      ).choices([...environmentNames()]),
    );
  const commandPath = preflight.parseOptions([...argv]).operands;
  const environment = preflight.opts<{ readonly environment?: string }>().environment;
  if (environment !== undefined) process.env.API_ENV = environment;
  const rootCommand = commandPath.at(0);
  if (rootCommand === undefined) return true;
  if (["auth", "update"].includes(rootCommand)) return false;
  if (administrationNamespace(rootCommand)) return true;
  if (optionScan.some((entry) => entry === "--help" || entry === "-h")) return false;
  if (["batch", "command-catalog", "completion", "docs", "help"].includes(rootCommand)) return true;
  const spec = specs.find(
    (candidate) =>
      commandPathMatches(commandPath, candidate.cliPath) ||
      (candidate.cliAliasPath !== undefined &&
        commandPathMatches(commandPath, candidate.cliAliasPath)),
  );
  return spec === undefined || spec.auth !== "none";
}

/** A generated leaf remains selected when its options follow the complete command path. */
function commandPathMatches(argv: readonly string[], commandPath: readonly string[]): boolean {
  return commandPath.every((segment, index) => argv[index] === segment);
}
