import { Command, Option } from "commander";
import { RESULT_ENVELOPE_BYTE_CAP } from "../api/result-envelope.ts";

export type CliOutputMode = "text" | "data" | "data-full" | "json";

/**
 * What an unflagged command prints.
 *  - `auto`: clean text on an interactive terminal, `--data` JSON when stdout is piped or
 *    redirected. Every command whose stdout contract IS the result envelope uses this, so a
 *    caller that forgets `--data` still parses JSON instead of misreading compacted text.
 *  - `text`: always text. For commands that render their own machine-readable stdout
 *    (`command-catalog search|show|dump --format lines|ndjson|json`, `command-catalog unified`),
 *    where wrapping the render in an envelope would break the grep/parse contract and put the
 *    dump through the 50KB envelope cap.
 */
export type CliOutputModeDefault = "auto" | "text";

export type CliOutputOptions = {
  readonly text?: boolean;
  readonly data?: boolean;
  readonly dataFull?: boolean;
  readonly json?: boolean;
  readonly agentChassis?: unknown;
  readonly agentModel?: unknown;
};

const CAP_KB = `${RESULT_ENVELOPE_BYTE_CAP / 1_000}KB`;

export const OUTPUT_MODE_OPTION_SPECS = [
  {
    flags: "--text",
    description:
      "output mode switch, takes no value: print clean text on stdout (default on an interactive terminal); pass it explicitly to keep text when stdout is piped or redirected",
    conflicts: ["data", "dataFull", "json"],
  },
  {
    flags: "--data",
    description: `output mode switch, takes no value: print the response data payload as JSON on stdout (default when stdout is not a terminal); over-${CAP_KB} results print the capped envelope (truncated: true) instead. This selects how the response is printed and never carries a request body — pass request fields through the command's own named options`,
    conflicts: ["text", "dataFull", "json"],
  },
  {
    flags: "--data-full",
    description:
      "output mode switch, takes no value: print the complete response data payload as JSON on stdout with no byte cap; for programmatic consumers that bound their own reads, never for LLM agents",
    conflicts: ["text", "data", "json"],
  },
  {
    flags: "--json",
    description: `output mode switch, takes no value: print the stable JSON envelope on stdout (capped at ${CAP_KB})`,
    conflicts: ["text", "data", "dataFull"],
  },
] as const;

export function addOutputModeOptions(command: Command): Command {
  for (const spec of OUTPUT_MODE_OPTION_SPECS) {
    command.addOption(new Option(spec.flags, spec.description).conflicts([...spec.conflicts]));
  }
  return command;
}

/**
 * Explicit output-mode flags always win. Without one, an agent-provenance pair or a non-interactive
 * stdout selects `data`, so piped and redirected output is machine-readable by default; `whenUnset`
 * is `"text"` for commands that own their stdout rendering.
 */
export function resolveOutputMode(
  opts: CliOutputOptions,
  whenUnset: CliOutputModeDefault = "auto",
): CliOutputMode {
  if (opts.json === true) return "json";
  if (opts.dataFull === true) return "data-full";
  if (opts.data === true) return "data";
  if (opts.text === true) return "text";
  if (hasAgentProvenancePair(opts)) return "data";
  // Node leaves `isTTY` undefined on a non-tty stdout, so the negation covers pipes and files.
  return whenUnset === "auto" && !process.stdout.isTTY ? "data" : "text";
}

/**
 * Whether this CLI invocation reserves stdout for a machine consumer — the same flag-then-TTY rule
 * `resolveOutputMode` applies, read from argv before any command is constructed. The CLI entry hands
 * it to `setStderrLogging` so stderr stays clear of routine noise for a `2>&1` reader; the MCP
 * server never calls it and keeps full stderr diagnostics.
 */
export function cliMachineOutputSelected(argv: readonly string[]): boolean {
  if (argv.includes("--text")) return false;
  return (
    argv.includes("--json") ||
    argv.includes("--data") ||
    argv.includes("--data-full") ||
    // The provenance pair selects `data` in resolveOutputMode even on a terminal, so it reserves
    // stderr for the same consumer.
    (argv.includes("--agent-chassis") && argv.includes("--agent-model")) ||
    !process.stdout.isTTY
  );
}

export function outputModeJsonAccept(mode: CliOutputMode): boolean {
  return mode === "data" || mode === "data-full" || mode === "json";
}

function hasAgentProvenancePair(opts: CliOutputOptions): boolean {
  return nonBlankString(opts.agentChassis) && nonBlankString(opts.agentModel);
}

function nonBlankString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}
